-- Peças reais do catálogo da LIVÍ no WhatsApp (outubro de 2026), no lugar das fictícias.
-- Fotos em public/img/pecas/<coleção>/<peça>/ (grande e pequena, -p).
-- Estoque: as peças com "APENAS 1 NO M" no catálogo entram com essa unidade só;
-- as outras entram com 1 por tamanho, do PP ao GG, até a Livia acertar no painel.

DELETE FROM pecas WHERE slug IN ('vestido-lumina', 'vestido-lumina-midi', 'top-lumina-halter', 'saia-lumina-fluida', 'vestido-velvet', 'vestido-velvet-longo', 'top-velvet-drapeado', 'saia-velvet', 'conjunto-carmim', 'top-carmim-drapeado', 'saia-carmim', 'vestido-carmim-longo', 'vestido-confianca', 'corset-confianca', 'vestido-confianca-midi', 'saia-lapis-confianca');







